import { execFile } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { promisify } from 'node:util';

const PROJECT = '/home/lynxadmin/project/bid-scaning';
const run = promisify(execFile);

try {
  const res = await run('/usr/bin/python3', ['run_pipeline.py'], {
    cwd: PROJECT,
    timeout: 300000,
    maxBuffer: 10485760,
  });
  return { json: { ok: true, out: (res.stdout || '').trim().slice(-500) } };
} catch (e) {
  const detail = String(e.stderr || e.stdout || e).slice(-400);
  try {
    const env = readFileSync(PROJECT + '/.env', 'utf8');
    const tok = (/TG_TOKEN=(.*)/.exec(env) || [])[1]?.trim();
    const chat = (/TG_CHAT_ID=(.*)/.exec(env) || [])[1]?.trim();
    if (tok && chat) {
      await run('curl', ['-s', '--max-time', '20', '-o', '/dev/null', '-X', 'POST',
        `https://api.telegram.org/bot${tok}/sendMessage`,
        '--data-urlencode', `chat_id=${chat}`,
        '--data-urlencode', `text=⚠️ bid-scan run FAILED: ${detail}`]);
    }
  } catch {}
  throw new Error(detail);
}
